// Fixed CalDAV collection of the Nextcloud calendar "Payments" (user pi.hole).
// The user in the URL must be the user of the "Nextcloud CalDAV – Payments" credential.
return [{ json: { calendarUrl: "http://nextcloud/remote.php/dav/calendars/pi.hole/Payments/" } }];

const calendarUrl = $("Payments calendar").first().json.calendarUrl;
if (!calendarUrl) {
  throw new Error("Payments calendar URL is missing");
}

function amountLabel(attributes) {
  const currency = attributes.currency_code || "";
  const format = (value) => {
    const number = Number(String(value ?? "").replace(/\s/g, ""));
    return Number.isFinite(number) ? number.toFixed(2) : String(value ?? "");
  };
  const min = format(attributes.amount_min);
  const max = format(attributes.amount_max);
  const amount = min === max ? min : `${min}-${max}`;
  return `${amount} ${currency}`.trim();
}

function nextDate(attributes) {
  const sources = [attributes.next_expected_match].concat(attributes.pay_dates || []);
  for (const source of sources) {
    const match = String(source || "").match(/^(\d{4}-\d{2}-\d{2})/);
    if (match) return match[1];
  }
  return "";
}

function icsEscape(value) {
  return String(value)
    .replace(/\\/g, "\\\\")
    .replace(/\r\n|\n|\r/g, "\\n")
    .replace(/,/g, "\\,")
    .replace(/;/g, "\\;");
}

function compact(isoDate) {
  return isoDate.replace(/-/g, "");
}

function nextDay(isoDate) {
  const [year, month, day] = isoDate.split("-").map(Number);
  const date = new Date(Date.UTC(year, month - 1, day + 1));
  const pad = (value) => String(value).padStart(2, "0");
  return `${date.getUTCFullYear()}${pad(date.getUTCMonth() + 1)}${pad(date.getUTCDate())}`;
}

function stamp() {
  return new Date().toISOString().replace(/[-:]/g, "").replace(/\.\d{3}Z$/, "Z");
}

const bills = [];
for (const item of $input.all()) {
  const rows = Array.isArray(item.json && item.json.data) ? item.json.data : [];
  bills.push(...rows);
}

const events = [];
for (const bill of bills) {
  const attributes = bill.attributes || {};
  if (attributes.active === false) continue;
  const date = nextDate(attributes);
  if (!date) continue;
  const id = String(bill.id);
  const name = attributes.name || `Firefly bill ${id}`;
  const amount = amountLabel(attributes);
  const description = [`Amount: ${amount}`, `Next date: ${date}`, `Firefly id: ${id}`].join("\n");
  const ics = [
    "BEGIN:VCALENDAR",
    "VERSION:2.0",
    "PRODID:-//homelab//firefly-subscriptions//EN",
    "CALSCALE:GREGORIAN",
    "BEGIN:VEVENT",
    `UID:firefly-bill-${id}@homelab`,
    `DTSTAMP:${stamp()}`,
    `DTSTART;VALUE=DATE:${compact(date)}`,
    `DTEND;VALUE=DATE:${nextDay(date)}`,
    `SUMMARY:${icsEscape(`${name} (${amount})`)}`,
    `DESCRIPTION:${icsEscape(description)}`,
    "END:VEVENT",
    "END:VCALENDAR",
    "",
  ].join("\r\n");
  const base = calendarUrl.endsWith("/") ? calendarUrl : `${calendarUrl}/`;
  events.push({
    json: {
      url: `${base}firefly-bill-${id}.ics`,
      ics,
      fireflyId: id,
      name,
      amount,
      nextDate: date,
    },
  });
}
return events;
